    const tierA = ppA?.tier || sweatScores[a.id]?.tier || getSweatScoreForGame(a, gamesSport)?.tier || '';
    const tierB = ppB?.tier || sweatScores[b.id]?.tier || getSweatScoreForGame(b, gamesSport)?.tier || '';
